package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"
)

var auditLog *os.File

func init() {
	var err error
	auditLog, err = os.OpenFile("/var/log/app/audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Fatal(err)
	}
}

// logAction writes an audit entry using the caller-supplied format description
func logAction(action string, username string, detail string) {
	// Build audit line with user-controlled detail field
	entry := fmt.Sprintf("ACTION=%s USER=%s DETAIL="+detail+"\n", action, username)
	auditLog.WriteString(entry)
}

// renderGreeting uses text/template to build a personalized page
func renderGreeting(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	if name == "" {
		name = "guest"
	}

	// Sanitize for XSS but not for template injection
	name = strings.ReplaceAll(name, "<", "&lt;")
	name = strings.ReplaceAll(name, ">", "&gt;")

	tmplStr := fmt.Sprintf(`<html><body><h1>Welcome, %s!</h1>
<p>Your session token: {{.Token}}</p>
<p>Internal build: {{.Build}}</p>
</body></html>`, name)

	tmpl, err := template.New("greeting").Parse(tmplStr)
	if err != nil {
		http.Error(w, "Template error", 500)
		return
	}

	data := struct {
		Token string
		Build string
	}{
		Token: r.Header.Get("X-Session-Token"),
		Build: os.Getenv("BUILD_HASH"),
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, data)
}

// handleReport processes user-submitted reports
func handleReport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	r.ParseForm()
	reportType := r.FormValue("type")
	description := r.FormValue("description")
	username := r.FormValue("username")

	if reportType == "" || description == "" {
		http.Error(w, "Missing fields", 400)
		return
	}

	// Log the report submission - description is user-controlled
	// and passed directly as format string component
	logAction("REPORT_SUBMIT", username, description)

	// Also use fmt.Fprintf with user data for response
	responseMsg := fmt.Sprintf("Report received: type=%s, submitter=%s", reportType, username)
	fmt.Fprintf(w, responseMsg)
	fmt.Fprintf(w, "\nDetail logged: "+description)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/greet", renderGreeting)
	http.HandleFunc("/report", handleReport)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
